/// C bindings of the census and diagnostics platform headers (generated by build.rs),
/// re-exported with the public SDK ones.
#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code,
    clippy::all
)]
mod sys {
    pub use rsf_game_sys::*;
    include!(concat!(env!("OUT_DIR"), "/sys.rs"));
}
#[cfg(windows)]
mod windows;

#[cfg(windows)]
mod launcher;

#[cfg(windows)]
mod diagnostics;

#[cfg(all(windows, target_env = "msvc"))]
mod census;

#[cfg(windows)]
#[unsafe(no_mangle)]
extern "C" fn rsf_get_bootstrap_version_impl() -> *const std::ffi::c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}
